create or replace function public.search_estate_subscribers(_search text default null,_estate_code text default null,_status text default null) returns setof public.estate_subscriptions language sql security definer set search_path=public as $$ select s from public.estate_subscriptions s where (public.admin_has_permission('admin:all',auth.uid()) or public.admin_has_permission('admin:manage_users',auth.uid()) or public.admin_has_permission('admin:approve_payments',auth.uid())) and (_search is null or s.subscription_number ilike '%'||_search||'%' or s.estate_name ilike '%'||_search||'%' or coalesce(s.order_id::text,'') ilike '%'||_search||'%' or coalesce(s.user_id::text,'') ilike '%'||_search||'%') and (_estate_code is null or s.estate_code=_estate_code) and (_status is null or s.subscription_status=_status) order by s.created_at desc $$;
create or replace function public.estate_code_from_name(_name text) returns text language plpgsql immutable as $$ declare cleaned text; parts text[]; result text:=''; p text; begin if _name ilike 'Precious Gardens%' then return 'PGE'; elsif _name ilike 'The Ambassadors Parks and Gardens%' or _name ilike 'The Ambassadors%' then return 'APG'; elsif _name ilike 'Hampton Court%' then return 'HCE'; end if; cleaned:=regexp_replace(coalesce(_name,''),'\s*(Estate|Scheme|Phase|\-|–|—).*$', '', 'gi'); parts:=regexp_split_to_array(trim(cleaned),'\s+'); foreach p in array parts loop if p<>'' and lower(p) not in ('the','and','of','at','in','on','a') then result:=result||upper(left(p,1)); end if; end loop; return upper(left(result,3)); end; $$;
create or replace function public.issue_estate_subscription_for_order() returns trigger language plpgsql security definer set search_path=public as $$ declare item jsonb; pname text; pcode text; pplan text; pproperty uuid; existing public.estate_subscriptions; begin if new.payment_status not in ('awaiting_approval','paid','completed') then return new; end if; select * into existing from public.estate_subscriptions where order_id=new.id limit 1; if existing.id is not null then return new; end if; item:=coalesce(new.items->0,'{}'::jsonb); pname:=coalesce(item->>'property_name',item->>'estate_name','Estate Subscription'); pcode:=public.estate_code_from_name(pname); if pcode is null or length(pcode)=0 then pcode:='EST'; end if; pplan:=coalesce(item->>'payment_plan',item->>'plan_type'); begin pproperty:=(item->>'property_id')::uuid; exception when others then pproperty:=null; end; perform public.create_estate_subscription(lower(regexp_replace(pname,'[^a-z0-9]+','_','gi')) ,pname,pcode,pproperty,new.user_id,new.id,null,new.total_amount,pplan,case when new.payment_status='paid' or new.payment_status='completed' then 'active' else 'pending' end); return new; end; $$;
drop trigger if exists trg_issue_estate_subscription on public.orders;
create trigger trg_issue_estate_subscription after insert or update of payment_status,items,total_amount on public.orders for each row execute function public.issue_estate_subscription_for_order();
revoke all on function public.estate_code_from_name(text) from public;
revoke all on function public.issue_estate_subscription_for_order() from public;
